module Top;
 typedef enum logic [3:0] {ZERO = 4'd0, ONE = 4'd1} Bit;
 class Item;
 endclass
 Item h;
 Bit b;
 initial begin
  b = ONE;
  $display("[%0d %s]", $cast(b, h), b.name());
  h = new;
  $display("[%0d %s]", $cast(b, h), b.name());
  $display("[%0d %s]", $cast(b, null), b.name());
 end
endmodule
